  TrustedConnectionController.binding=null;GroupMessages owner=new GroupMessages(new Context(root.resolve("real-timer-owner").toFile()),ownerSession,new GroupIdentity(a)),member=new GroupMessages(new Context(root.resolve("real-timer-member").toFile()),memberSession,new GroupIdentity(b));java.util.concurrent.atomic.AtomicBoolean pumping=new java.util.concurrent.atomic.AtomicBoolean(true);java.util.concurrent.CompletableFuture<Void> chunkSent=new java.util.concurrent.CompletableFuture<>();java.util.concurrent.atomic.AtomicReference<Throwable> failed=new java.util.concurrent.atomic.AtomicReference<>();String id=String.format("%032x",nextId++);Thread network=null;SystemClock.startReal();
