   network=new Thread(()->{try{while(pumping.get()){for(int side=0;side<2;side++){GroupSession from=side==0?ownerSession:memberSession;GroupMessages to=side==0?member:owner;GroupSession target=side==0?memberSession:ownerSession;String sender=side==0?a.pin:b.pin;GroupSession.Frame frame;while((frame=from.frames.poll())!=null){if(!frame.live.getAsBoolean())continue;GroupTextAuthority.Grant grant=new GroupTextAuthority.Grant(target.state,sender,()->true);if(frame.body.has("op")){to.incomingControl(grant,frame.body);if(frame.body.optString("op").equals("image-chunk")&&frame.body.optString("id").equals(id))chunkSent.complete(null);}else to.incoming(grant,frame.body,false);}}Thread.sleep(10);}}catch(Throwable error){failed.set(error);chunkSent.completeExceptionally(error);}},"declared-loopback-message-link");network.setDaemon(true);network.start();
